@dataclass(frozen=True)
class ResourceSample:
    elapsed_s: float
    gpu_memory_used_mib: float
    gpu_memory_free_mib: float
    gpu_process_memory_mib: float | None
    gpu_util_percent: float | None
    power_w: float | None
    system_cpu_percent: float | None
